// ──────────────────────────── tests ──────────────────────────────────────

test('next() hands back the first value with done false', () => {
  eq(makeIterator(['a', 'b']).next(), { value: 'a', done: false });
});

test('walks the values in order', () => {
  const it = makeIterator([10, 20]);
  eq(it.next(), { value: 10, done: false });
  eq(it.next(), { value: 20, done: false });
});

test('reports done once the values run out', () => {
  const it = makeIterator(['only']);
  it.next();
  eq(it.next(), { value: undefined, done: true });
});

test('stays done on every later call', () => {
  const it = makeIterator([]);
  eq(it.next(), { value: undefined, done: true });
  eq(it.next(), { value: undefined, done: true });
});

test('two iterators over the same array are independent', () => {
  const items = [1, 2, 3];
  const a = makeIterator(items);
  const b = makeIterator(items);
  eq(a.next().value, 1);
  eq(a.next().value, 2);
  eq(b.next().value, 1);
});

test('drain collects every value', () => {
  eq(drain(makeIterator([1, 2, 3])), [1, 2, 3]);
});

test('drain of a half-used iterator returns only what is left', () => {
  const it = makeIterator(['a', 'b', 'c']);
  it.next();
  eq(drain(it), ['b', 'c']);
});

test('drain of an exhausted iterator is empty', () => {
  const it = makeIterator([1]);
  ok(drain(it).length === 1);
  eq(drain(it), []);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('spreads into an array', () => {
  eq([...range(1, 4)], [1, 2, 3]);
});

test('works in a for-of loop', () => {
  const seen = [];
  for (const n of range(3, 6)) seen.push(n);
  eq(seen, [3, 4, 5]);
});

test('honours a step', () => {
  eq([...range(0, 10, 3)], [0, 3, 6, 9]);
});

test('is empty when start is not below end', () => {
  eq([...range(5, 5)], []);
  eq([...range(9, 2)], []);
});

test('is a plain object with its own fields, not an array', () => {
  const r = range(2, 5);
  eq(r.start, 2);
  eq(r.end, 5);
  ok(!Array.isArray(r), 'range should not return an array');
});

test('can be iterated twice — each loop gets a fresh iterator', () => {
  const r = range(1, 4);
  eq([...r], [1, 2, 3]);
  eq([...r], [1, 2, 3]);
});

test('Array.from and destructuring use the same protocol', () => {
  eq(Array.from(range(1, 4)), [1, 2, 3]);
  const [first, second] = range(10, 100, 5);
  eq([first, second], [10, 15]);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('sumOf adds up an array', () => {
  eq(sumOf([1, 2, 3, 4]), 10);
});

test('sumOf handles an empty iterable', () => {
  eq(sumOf([]), 0);
  eq(sumOf(new Set()), 0);
});

test('sumOf works on a Set, which drops duplicates first', () => {
  eq(sumOf(new Set([1, 1, 2, 3])), 6);
});

test('toArray copies an array and splits a string', () => {
  eq(toArray([1, 2]), [1, 2]);
  eq(toArray('hi'), ['h', 'i']);
});

test('toArray of a Map gives [key, value] pairs', () => {
  eq(
    toArray(
      new Map([
        ['a', 1],
        ['b', 2],
      ])
    ),
    [
      ['a', 1],
      ['b', 2],
    ]
  );
});

test('nth is 0-based and works on strings', () => {
  eq(nth(['a', 'b', 'c'], 1), 'b');
  eq(nth('abc', 0), 'a');
});

test('nth returns undefined past the end', () => {
  eq(nth([1, 2], 5), undefined);
  eq(nth(new Set(), 0), undefined);
});

test('all three work on a hand-rolled iterable', () => {
  eq(toArray(letters), ['x', 'y', 'z']);
  eq(nth(letters, 2), 'z');
  eq(sumOf([1, 2]), 3);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('countUpTo yields 1 through the limit', () => {
  eq([...countUpTo(5)], [1, 2, 3, 4, 5]);
});

test('countUpTo of 1 yields a single value', () => {
  eq([...countUpTo(1)], [1]);
});

test('countUpTo of 0 yields nothing', () => {
  eq([...countUpTo(0)], []);
  eq([...countUpTo(-3)], []);
});

test('a generator object works in for-of', () => {
  const seen = [];
  for (const n of countUpTo(3)) seen.push(n);
  eq(seen, [1, 2, 3]);
});

test('a generator object is one-shot', () => {
  const g = countUpTo(3);
  eq([...g], [1, 2, 3]);
  eq([...g], [], 'the second read finds an exhausted generator');
});

test('repeat yields the same value n times', () => {
  eq([...repeat('ok', 3)], ['ok', 'ok', 'ok']);
});

test('repeat of 0 times yields nothing', () => {
  eq([...repeat('ok', 0)], []);
});

test('Array.from works on a generator object too', () => {
  eq(Array.from(repeat(7, 2)), [7, 7]);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('calling trace runs none of the body', () => {
  const log = [];
  const g = trace(log);
  eq(log, [], 'a generator call must not execute anything');
  eq(g.next().value, 'a');
  eq(log, ['start']);
});

test('the first next() stops at the first yield', () => {
  const log = [];
  const g = trace(log);
  eq(g.next(), { value: 'a', done: false });
  eq(log, ['start'], 'it must not run past the first yield');
});

test('the second next() resumes after that yield', () => {
  const log = [];
  const g = trace(log);
  g.next();
  eq(g.next(), { value: 'b', done: false });
  eq(log, ['start', 'middle']);
});

test('the third next() finishes and reports the return value', () => {
  const log = [];
  const g = trace(log);
  g.next();
  g.next();
  eq(g.next(), { value: 'done!', done: true });
  eq(log, ['start', 'middle', 'end']);
});

test('every next() after that is done with undefined', () => {
  const g = trace([]);
  g.next();
  g.next();
  g.next();
  eq(g.next(), { value: undefined, done: true });
  eq(g.next(), { value: undefined, done: true });
});

test('for-of and spread collect the yields and drop the return', () => {
  eq([...trace([])], ['a', 'b']);
});

test('runToCompletion hands back the returned value', () => {
  eq(runToCompletion(trace([])), 'done!');
});

test('runToCompletion works on any generator object', () => {
  eq(runToCompletion(twoThenTotal()), 3);
  eq(runToCompletion(twoThenTotal()), 3);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('concatAll joins two arrays end to end', () => {
  eq([...concatAll([1, 2], [3])], [1, 2, 3]);
});

test('concatAll takes any mix of iterables', () => {
  const nested = concatAll([9]);
  eq([...concatAll([1, 2], 'ab', new Set([7, 7]), nested)], [
    1,
    2,
    'a',
    'b',
    7,
    9,
  ]);
});

test('concatAll with no arguments yields nothing', () => {
  eq([...concatAll()], []);
  eq([...concatAll([], '')], []);
});

test('deepFlatten flattens to any depth', () => {
  eq([...deepFlatten([1, [2, [3, [4]]]])], [1, 2, 3, 4]);
});

test('deepFlatten treats strings as atoms', () => {
  eq([...deepFlatten([['a'], ['bc', ['d']]])], ['a', 'bc', 'd']);
});

test('deepFlatten descends into Sets and generators too', () => {
  eq([...deepFlatten([1, new Set([2, 3]), [concatAll([4])]])], [1, 2, 3, 4]);
});

test('deepFlatten of nothing but empties is empty', () => {
  eq([...deepFlatten([])], []);
  eq([...deepFlatten([[], [[]]])], []);
});

test('deepFlatten stays lazy on an endless branch', () => {
  const it = deepFlatten([1, forever(9)])[Symbol.iterator]();
  eq([it.next().value, it.next().value, it.next().value], [1, 9, 9]);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('take pulls the first n values of an endless generator', () => {
  eq([...take(5, naturals())], [1, 2, 3, 4, 5]);
});

test('take of 0 yields nothing and does not hang', () => {
  eq([...take(0, naturals())], []);
});

test('naturals starts over at 1 on every call', () => {
  eq([...take(3, naturals())], [1, 2, 3]);
  eq([...take(3, naturals())], [1, 2, 3]);
});

test('take works on a plain array', () => {
  eq([...take(2, ['a', 'b', 'c'])], ['a', 'b']);
});

test('take of more than exists gives everything', () => {
  eq([...take(9, [1, 2])], [1, 2]);
  eq([...take(3, [])], []);
});

test('take works on strings and Sets', () => {
  eq([...take(9, 'hi')], ['h', 'i']);
  eq([...take(2, new Set([4, 5, 6]))], [4, 5]);
});

test('take returns something lazy, not an array', () => {
  const t = take(2, [1, 2, 3]);
  ok(!Array.isArray(t), 'take should hand back an iterable, not an array');
  eq([...t], [1, 2]);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('cycle loops back to the start', () => {
  eq([...take(7, cycle(['a', 'b', 'c']))], ['a', 'b', 'c', 'a', 'b', 'c', 'a']);
});

test('cycle of a single item repeats it', () => {
  eq([...take(3, cycle(['x']))], ['x', 'x', 'x']);
});

test('cycle of an empty collection ends instead of spinning', () => {
  eq([...take(3, cycle([]))], []);
});

test('cycle works on any iterable, including a string', () => {
  eq([...take(4, cycle('ab'))], ['a', 'b', 'a', 'b']);
  eq([...take(3, cycle(new Set([7, 8])))], [7, 8, 7]);
});

test('cycle remembers a source that can only be walked once', () => {
  eq([...take(5, cycle(onceOneTwo()))], [1, 2, 1, 2, 1]);
});

test('fibonacci starts 0, 1 and adds the last two', () => {
  eq([...take(8, fibonacci())], [0, 1, 1, 2, 3, 5, 8, 13]);
});

test('fibonacci keeps going correctly', () => {
  const first20 = [...take(20, fibonacci())];
  eq(first20.length, 20);
  eq(first20[19], 4181);
});

test('each fibonacci() call starts a fresh sequence', () => {
  eq([...take(3, fibonacci())], [0, 1, 1]);
  eq([...take(3, fibonacci())], [0, 1, 1]);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('mapIter transforms every value', () => {
  eq([...mapIter([1, 2, 3], (n) => n * 2)], [2, 4, 6]);
});

test('mapIter hands the callback the index as well', () => {
  eq([...mapIter('ab', (c, i) => c + i)], ['a0', 'b1']);
});

test('mapIter returns a lazy iterable, not an array', () => {
  const m = mapIter(new Set([1, 2]), (n) => n);
  ok(!Array.isArray(m), 'mapIter should not build an array');
  eq([...m], [1, 2]);
});

test('filterIter keeps only the matching values', () => {
  eq([...filterIter([1, 2, 3, 4], (n) => n % 2 === 1)], [1, 3]);
  eq([...filterIter([1, 2], () => false)], []);
});

test('filterIter indexes the values going in, not the ones kept', () => {
  eq([...filterIter('abcd', (c, i) => i % 2 === 0)], ['a', 'c']);
});

test('both handle an empty source', () => {
  eq([...mapIter([], (n) => n)], []);
  eq([...filterIter('', () => true)], []);
});

test('mapIter is lazy — it only maps what is consumed', () => {
  const src = counted([1, 2, 3, 4, 5]);
  const double = spy((n) => n * 2);
  eq([...take(2, mapIter(src.iterable, double))], [2, 4]);
  ok(src.log.pulls <= 3, `pulled ${src.log.pulls} values for 2 results`);
  ok(double.callCount <= 3, `called fn ${double.callCount} times for 2`);
});

test('they compose over an endless source', () => {
  const evens = filterIter(naturals(), (n) => n % 2 === 0);
  eq([...take(3, mapIter(evens, (n) => n * 10))], [20, 40, 60]);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('chunked groups values and keeps a short last group', () => {
  eq(
    [...chunked([1, 2, 3, 4, 5, 6, 7], 3)],
    [[1, 2, 3], [4, 5, 6], [7]]
  );
});

test('chunked leaves no tail when it divides evenly', () => {
  eq([...chunked([1, 2, 3, 4], 2)], [[1, 2], [3, 4]]);
});

test('chunked works on any iterable', () => {
  eq([...chunked('abc', 2)], [['a', 'b'], ['c']]);
  eq([...chunked(new Set([1, 2, 3]), 5)], [[1, 2, 3]]);
});

test('chunked of an empty source yields no groups at all', () => {
  eq([...chunked([], 3)], []);
});

test('windows slides one value at a time', () => {
  eq([...windows([1, 2, 3, 4], 2)], [[1, 2], [2, 3], [3, 4]]);
});

test('windows needs a full window before it yields anything', () => {
  eq([...windows([1, 2], 3)], []);
  eq([...windows([1, 2, 3], 3)], [[1, 2, 3]]);
});

test('each window is a separate array, not a shared buffer', () => {
  const all = [...windows('abcd', 2)];
  all[0].push('!');
  eq(all[1], ['b', 'c']);
});

test('both stay lazy on an endless source', () => {
  eq([...take(2, chunked(naturals(), 2))], [[1, 2], [3, 4]]);
  eq([...take(2, windows(naturals(), 3))], [[1, 2, 3], [2, 3, 4]]);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('zipIter pairs values position by position', () => {
  eq([...zipIter([1, 2], ['a', 'b'])], [[1, 'a'], [2, 'b']]);
});

test('zipIter stops when the shorter side runs out', () => {
  eq([...zipIter([1, 2, 3], 'ab')], [[1, 'a'], [2, 'b']]);
  eq([...zipIter('ab', [1, 2, 3])], [['a', 1], ['b', 2]]);
});

test('zipIter with an empty side yields nothing', () => {
  eq([...zipIter([], [1, 2])], []);
  eq([...zipIter([1, 2], '')], []);
});

test('zipIter can pair a finite source with an endless one', () => {
  eq([...zipIter('abc', naturals())], [['a', 1], ['b', 2], ['c', 3]]);
});

test('zipIter mixes iterable types happily', () => {
  eq([...zipIter(new Set([7, 8]), 'xy')], [[7, 'x'], [8, 'y']]);
});

test('enumerate pairs a 0-based index with each value', () => {
  eq([...enumerate('ab')], [[0, 'a'], [1, 'b']]);
  eq([...enumerate([])], []);
});

test('enumerate can start counting somewhere else', () => {
  eq([...enumerate(['a', 'b'], 1)], [[1, 'a'], [2, 'b']]);
});

test('enumerate is lazy and works on any iterable', () => {
  eq([...enumerate(new Set(['x']))], [[0, 'x']]);
  eq([...take(2, enumerate(naturals(), 5))], [[5, 1], [6, 2]]);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('the priming pull yields the starting total', () => {
  eq(accumulator().next(), { value: 0, done: false });
});

test('a sent value is added to the total', () => {
  const g = accumulator();
  g.next();
  eq(g.next(5), { value: 5, done: false });
});

test('the total accumulates across pulls', () => {
  const g = accumulator();
  g.next();
  g.next(5);
  eq(g.next(3).value, 8);
  eq(g.next(-8).value, 0);
});

test('the value sent to the FIRST next() is thrown away', () => {
  eq(accumulator().next(99).value, 0);
});

test('two accumulators keep separate totals', () => {
  const a = accumulator();
  const b = accumulator();
  a.next();
  b.next();
  a.next(10);
  eq(b.next(1).value, 1);
});

test('drive returns one yielded value per input', () => {
  eq(drive(accumulator(), [1, 2, 3]), [1, 3, 6]);
});

test('drive with no inputs returns nothing', () => {
  eq(drive(accumulator(), []), []);
});

test('drive works on any two-way generator', () => {
  eq(drive(calculator(), [['add', 2], ['mul', 5], ['reset']]), [2, 10, 0]);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('collectAsync drains a ticker in order', async () => {
  eq(await collectAsync(ticker(['a', 'b', 'c'], 2)), ['a', 'b', 'c']);
});

test('the values really are spread out over time', async () => {
  const started = Date.now();
  await collectAsync(ticker([1, 2, 3], 5));
  ok(Date.now() - started >= 5, 'ticker should await between values');
});

test('a ticker with no values finishes immediately', async () => {
  eq(await collectAsync(ticker([], 5)), []);
});

test('collectAsync works on any async iterable', async () => {
  eq(await collectAsync(asyncLetters()), ['x', 'y']);
});

test('an async generator object is one-shot too', async () => {
  const g = ticker(['a', 'b'], 1);
  eq(await collectAsync(g), ['a', 'b']);
  eq(await collectAsync(g), []);
});

test('takeAsync stops an endless async source', async () => {
  eq(await collectAsync(takeAsync(3, asyncNaturals())), [1, 2, 3]);
});

test('takeAsync of 0 yields nothing', async () => {
  eq(await collectAsync(takeAsync(0, asyncNaturals())), []);
});

test('takeAsync of more than exists gives everything', async () => {
  eq(await collectAsync(takeAsync(9, ticker(['a'], 1))), ['a']);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('it yields every item across every page', async () => {
  const api = makeApi(LETTERS, 3);
  eq(await collectAsync(paginate(api.fetchPage)), LETTERS);
});

test('it walks the cursors the API handed back', async () => {
  const api = makeApi(LETTERS, 3);
  await collectAsync(paginate(api.fetchPage));
  eq(api.calls, [0, 3, 6]);
});

test('nothing is fetched until the first pull', async () => {
  const api = makeApi(LETTERS, 3);
  const pages = paginate(api.fetchPage);
  eq(api.calls, [], 'creating the generator must not touch the API');
  await pages.next();
  eq(api.calls, [0]);
});

test('a consumer that stops early never fetches page two', async () => {
  const api = makeApi(LETTERS, 3);
  eq(await collectAsync(takeAsync(2, paginate(api.fetchPage))), ['a', 'b']);
  eq(api.calls, [0], 'page 2 was fetched but never needed');
});

test('it fetches the next page only when the consumer needs it', async () => {
  const api = makeApi(LETTERS, 3);
  const four = await collectAsync(takeAsync(4, paginate(api.fetchPage)));
  eq(four, ['a', 'b', 'c', 'd']);
  eq(api.calls, [0, 3]);
});

test('a single-page API costs one fetch', async () => {
  const api = makeApi(['x', 'y'], 10);
  eq(await collectAsync(paginate(api.fetchPage)), ['x', 'y']);
  eq(api.calls, [0]);
});

test('an empty API yields nothing and stops', async () => {
  const api = makeApi([], 3);
  eq(await collectAsync(paginate(api.fetchPage)), []);
  eq(api.calls, [0]);
});

test('it copes with a page size of one', async () => {
  const api = makeApi(['a', 'b', 'c'], 1);
  eq(await collectAsync(paginate(api.fetchPage)), ['a', 'b', 'c']);
  eq(api.calls, [0, 1, 2]);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('greetLoud runs the default export through the named one', () => {
  eq(greetLoud('ada'), 'HELLO, ADA!');
});

test('greetLoud works for any name', () => {
  eq(greetLoud('bo'), 'HELLO, BO!');
});

test('an alias is the same function under a different local name', () => {
  eq(greetLoud('x'), yell(greet('x')));
});

test('exportNames lists the named exports plus "default"', () => {
  eq(exportNames(), ['NAME', 'default', 'shout']);
});

test('the default import and namespace.default are one function', () => {
  eq(defaultIsSame(), true);
});

test('the module NAME is reachable both ways', () => {
  eq(NAME, greeting.NAME);
  eq(exportNames().includes('NAME'), true);
});

test('a namespace object cannot be patched from outside', () => {
  eq(tryMutateNamespace(), 'TypeError');
});

