test('aborting the signal ends the loop', async () => {
  const controller = new AbortController();
  const poll = spy(() => 'tick');
  const poller = new Poller(poll, {
    intervalMs: 5,
    signal: controller.signal,
  });
  const seen = [];
  for await (const value of poller) {
    seen.push(value);
    if (seen.length === 2) controller.abort();
  }
  eq(seen, ['tick', 'tick'], 'the loop must end on its own after the abort');
  eq(poll.callCount, 2);
});

test('a signal that is already aborted yields nothing', async () => {
  const controller = new AbortController();
  controller.abort();
  const poll = spy(() => 'tick');
  const seen = [];
  for await (const value of new Poller(poll, {
    intervalMs: 5,
    signal: controller.signal,
  })) {
    seen.push(value);
  }
  eq(seen, []);
  eq(poll.callCount, 0, 'an aborted poller must not poll even once');
});

test('breaking out stops the polling for good', async () => {
  const poll = spy(() => 'x');
  for await (const value of new Poller(poll, { intervalMs: 5 })) break;
  const afterBreak = poll.callCount;
  await sleep(15);
  eq(poll.callCount, afterBreak, 'nothing may keep polling after a break');
});

jstrain/08-iterators-generators-modules/.instructions:
**Concepts:** iterator protocol · next()  
**Level:** ★☆☆ warm-up

Before for-of, before generators, there is one tiny contract: an
ITERATOR is any object with a `next()` method that hands back
`{ value, done }`. Build one by hand so the rest of the module is
never magic.

    const it = makeIterator(['a', 'b']);
    it.next()   → { value: 'a', done: false }
    it.next()   → { value: 'b', done: false }
    it.next()   → { value: undefined, done: true }
    it.next()   → { value: undefined, done: true }   (stays done)

Then write drain(iterator): pull until done, collect the values.

    drain(makeIterator([1, 2, 3]))   → [1, 2, 3]

