  eq(
    [...flattenConfig(CONFIG)],
    [
      ['port', 8080],
      ['db.host', 'localhost'],
      ['db.creds.user', 'root'],
      ['db.ports', [5432, 5433]],
      ['debug', false],
      ['fallback', null],
    ]
  );
