test('an array is a value, not a branch to walk into', () => {
  eq([...flattenConfig({ ports: [1, 2] })], [['ports', [1, 2]]]);
});

test('null is a value even though typeof calls it an object', () => {
  eq([...flattenConfig({ a: null, b: { c: null } })], [
