  for (const value of iterable) {
    if (dropped < n) {
      dropped += 1;
      continue;
    }
    yield value;
  }
}

function* concatI(...iterables) {
  for (const iterable of iterables) yield* iterable;
}

function* naturals() {
  let n = 1;
  while (true) {
    yield n;
    n += 1;
  }
}

function counted(values) {
  const log = { pulls: 0 };
  const iterable = {
    [Symbol.iterator]() {
      const inner = values[Symbol.iterator]();
      return {
        next() {
          log.pulls += 1;
          return inner.next();
        },
      };
